local MiningChiselMaker = {}
local PRODUCTS = {
    iron_chisel = { name = "Železno dleto", ironCost = 2, woodCost = 1, leatherCost = 1, time = 4, cost = 120, prestige = 2, happiness = 1, description = "Železno dleto za klebanje kamna." },
    bronze_chisel = { name = "Bronasto dleto", bronzeCost = 2, ironCost = 1, woodCost = 1, leatherCost = 1, time = 6, cost = 300, prestige = 4, happiness = 2, description = "Bronasto dleto za trši kamen." },
    silver_chisel = { name = "Srebrno dleto", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 10, cost = 750, prestige = 8, happiness = 3, description = "Srebrno dleto za precizno klebanje." },
    gilded_chisel = { name = "Pozlačeno dleto", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 14, cost = 1650, prestige = 17, happiness = 4, description = "Pozlačeno dleto za dvorne kiparje." },
    jewel_set_chisel = { name = "Draguljasto dleto", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 18, cost = 3600, prestige = 31, happiness = 6, description = "Draguljasto dleto za kraljeve kiparje." },
    royal_sovereign_chisel = { name = "Kraljevsko suvereno dleto", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 25, cost = 7900, prestige = 62, happiness = 12, description = "Suvereno dleto z biseri za krono." },
}
local BUILDINGS = {
    chisel_workshop = { name = "Dletarska delavnica", cost = { gold = 290, wood = 150, stone = 110, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    chiseler_house = { name = "Dletarska hiša", cost = { gold = 1080, wood = 330, stone = 230, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_chisel_atelier = { name = "Mojstrski dletarski atelje", cost = { gold = 2850, wood = 390, stone = 470, silver = 31, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_carving_palace = { name = "Suverena klesarska palača", cost = { gold = 12200, wood = 600, stone = 810, gold = 79, jewel = 18 }, upkeep = 242, qualityBonus = 55, prestigeBonus = 50 },
}
MiningChiselMaker.ironStock = 12; MiningChiselMaker.bronzeStock = 10; MiningChiselMaker.woodStock = 14; MiningChiselMaker.leatherStock = 10; MiningChiselMaker.silverStock = 8; MiningChiselMaker.goldStock = 6; MiningChiselMaker.jewelStock = 4; MiningChiselMaker.pearlStock = 4
MiningChiselMaker.productStock = {}; MiningChiselMaker.buildings = {}; MiningChiselMaker.maker = nil; MiningChiselMaker.activeMaking = {}; MiningChiselMaker.totalProducts = 0; MiningChiselMaker.dayTimer = 0
function MiningChiselMaker.init() MiningChiselMaker.ironStock=12; MiningChiselMaker.bronzeStock=10; MiningChiselMaker.woodStock=14; MiningChiselMaker.leatherStock=10; MiningChiselMaker.silverStock=8; MiningChiselMaker.goldStock=6; MiningChiselMaker.jewelStock=4; MiningChiselMaker.pearlStock=4; MiningChiselMaker.productStock={}; MiningChiselMaker.buildings={}; MiningChiselMaker.maker=nil; MiningChiselMaker.activeMaking={}; MiningChiselMaker.totalProducts=0; MiningChiselMaker.dayTimer=0; print("[MiningChiselMaker] Royal Mining Chisel Maker System initialized (6 products, 4 buildings)") end
function MiningChiselMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MiningChiselMaker.maker={name=n or ("Dletar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dletar najet: %s (spretnost: %d)",MiningChiselMaker.maker.name,s),"success") end; return true end
function MiningChiselMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MiningChiselMaker.build(id) local ok,e=MiningChiselMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MiningChiselMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MiningChiselMaker.getQualityBonus() local b=0; for _,bd in ipairs(MiningChiselMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MiningChiselMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MiningChiselMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MiningChiselMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MiningChiselMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MiningChiselMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MiningChiselMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MiningChiselMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MiningChiselMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MiningChiselMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MiningChiselMaker.buildings==0 then return false,"Potrebna dletarska delavnica" end; if not MiningChiselMaker.maker then return false,"Potreben dletar" end; return true end
function MiningChiselMaker.make(pt,qty) qty=qty or 1; local ok,e=MiningChiselMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MiningChiselMaker.ironStock=MiningChiselMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MiningChiselMaker.bronzeStock=MiningChiselMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MiningChiselMaker.woodStock=MiningChiselMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MiningChiselMaker.leatherStock=MiningChiselMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MiningChiselMaker.silverStock=MiningChiselMaker.silverStock-d.silverCost*qty end; if d.goldCost then MiningChiselMaker.goldStock=MiningChiselMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MiningChiselMaker.jewelStock=MiningChiselMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MiningChiselMaker.pearlStock=MiningChiselMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MiningChiselMaker.maker then t=math.max(1,t-math.floor(MiningChiselMaker.maker.skill/13)) end; table.insert(MiningChiselMaker.activeMaking,{id="chisel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MiningChiselMaker.completeMaking(m) local q=1.0+(MiningChiselMaker.getQualityBonus()/100); if MiningChiselMaker.maker then q=q+(MiningChiselMaker.maker.skill/140) end; q=math.min(2.5,q); MiningChiselMaker.productStock[m.productType]=(MiningChiselMaker.productStock[m.productType] or 0)+m.quantity; MiningChiselMaker.totalProducts=MiningChiselMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MiningChiselMaker.maker then MiningChiselMaker.maker.itemsMade=MiningChiselMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MiningChiselMaker.maker.skill=math.min(100,MiningChiselMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dleto izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chisel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MiningChiselMaker.update(dt) if not _G.state then return end; MiningChiselMaker.dayTimer=MiningChiselMaker.dayTimer+dt; if MiningChiselMaker.dayTimer>=30 then MiningChiselMaker.dayTimer=0; for i=#MiningChiselMaker.activeMaking,1,-1 do local m=MiningChiselMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MiningChiselMaker.completeMaking(m); table.remove(MiningChiselMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MiningChiselMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MiningChiselMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MiningChiselMaker.getStats() return {ironStock=MiningChiselMaker.ironStock,bronzeStock=MiningChiselMaker.bronzeStock,woodStock=MiningChiselMaker.woodStock,leatherStock=MiningChiselMaker.leatherStock,silverStock=MiningChiselMaker.silverStock,goldStock=MiningChiselMaker.goldStock,jewelStock=MiningChiselMaker.jewelStock,pearlStock=MiningChiselMaker.pearlStock,productStock=MiningChiselMaker.productStock,numBuildings=#MiningChiselMaker.buildings,hasMaker=MiningChiselMaker.maker~=nil,makerName=MiningChiselMaker.maker and MiningChiselMaker.maker.name or "—",makerSkill=MiningChiselMaker.maker and MiningChiselMaker.maker.skill or 0,activeMaking=#MiningChiselMaker.activeMaking,totalProducts=MiningChiselMaker.totalProducts} end
return MiningChiselMaker
